/* Silnik kursów A-Z i lokalnego czatu pomocnika. Odpowiedzi oparte na danych bieżącej lekcji, bez wysyłania danych do serwera. */
(() => {
  'use strict';
  const sources = window.ACADEMY_ONLINE_SOURCES || [];
  const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const list = arr => `<ol class="az-list">${(arr||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol>`;
  const bullets = arr => `<ul class="az-bullets">${(arr||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;
  const profileDefs = [
    {id:'safety',re:/esd|bhp|bezpiecze|stanowisk|obudow|demontaż|otwieranie|narzędzia|montaż/i,label:'BHP, ESD i organizacja pracy',tools:['Mata i opaska ESD używane zgodnie z procedurą stanowiska','Zestaw precyzyjnych bitów i plastikowe otwieraki','Pojemniki na śruby, etykiety i aparat do dokumentacji','Instrukcja serwisowa dokładnego modelu','Oświetlenie i lupa'],prep:['Potwierdź model, numer seryjny i rewizję płyty.','Zapisz objawy i historię wcześniejszych napraw.','Utwórz kopię danych lub ustal, czy dane mają być zachowane.','Wyłącz urządzenie, odłącz zasilacz i postępuj według procedury odłączenia baterii.'],steps:['Przygotuj czyste, stabilne stanowisko i ogranicz źródła ładunków statycznych.','Wyrównaj potencjał maty, opaski i urządzenia zgodnie z instrukcją ESD.','Zrób zdjęcia przed demontażem; opisuj położenie śrub i przewodów.','Otwieraj obudowę narzędziem odpowiednim dla zatrzasków i nie używaj siły.','Po odłączeniu baterii sprawdź, czy nie ma uszkodzeń, korozji i śladów cieczy.','Przed złożeniem porównaj wszystkie złącza ze zdjęciami i instrukcją.'],solutions:['Jeżeli zatrzask stawia opór, sprawdź ukryte śruby zamiast podważać mocniej.','Jeżeli brakuje śrub lub występują różne długości, odtwórz mapę położeń.','Jeżeli element nosi ślady cieczy lub korozji, wstrzymaj uruchomienie i opracuj osobny plan inspekcji.'],tests:['Sprawdź, czy obudowa zamyka się bez szczelin i nadmiernego nacisku.','Sprawdź klawiaturę, touchpad, porty, głośniki i ekran.','Wykonaj test pierwotnego objawu i zapisz rezultat.'],mistakes:['Mieszanie śrub o różnych długościach.','Praca przy podłączonym zasilaczu lub baterii.','Podważanie płyty metalowym narzędziem.','Brak zdjęć przewodów przed odłączeniem.'],safety:'Nie otwieraj zasilacza sieciowego. Przy spuchniętej baterii, dymie, zapachu spalenizny, cieczy lub iskrzeniu przerwij pracę. Opaska ESD nie jest ochroną przed porażeniem elektrycznym.'},
    {id:'meter',re:/multimetr|woltomierz|napię|rezystanc|ciągłoś|pomiar|punkt pomiar|szyna|vrm|mosfet|zwarcie|bezpiecznik|kondensator|diode/i,label:'Elektronika i pomiary',tools:['Multimetr z przewodami o nieuszkodzonej izolacji','Dokumentacja schematu i BoardView dokładnej rewizji','Oświetlenie, lupa i karta zapisu pomiarów','Zasilacz laboratoryjny z ograniczeniem prądu — tylko dla przeszkolonego technika i według procedury','Ochrona ESD i narzędzia izolowane'],prep:['Rozpoznaj dokładny model płyty i rewizję PCB.','Znajdź punkt GND i nazwę badanej linii w schemacie.','Sprawdź stan przewodów, gniazd i bezpieczników miernika.','Zdecyduj, czy pomiar ma być wykonany przy zasilaniu, czy bez zasilania — nigdy nie zamieniaj tych trybów.'],steps:['Wybierz właściwy tryb i zakres miernika przed przyłożeniem sond.','Napięcie DC mierz równolegle do badanego punktu; nie zwieraj sąsiednich pinów.','Rezystancję i ciągłość mierz wyłącznie po odłączeniu wszystkich źródeł energii i bezpiecznym rozładowaniu zgodnie z instrukcją.','Zanotuj warunki pomiaru: stan płyty, zasilanie, punkt, polaryzację i zakres.','Porównaj wynik z dokumentacją dokładnej płyty i znaną dobrą wartością.','Powtórz pomiar w tych samych warunkach, aby ocenić jego powtarzalność.'],solutions:['Niski opór do masy nie dowodzi zwarcia — niektóre linie rdzeni CPU/GPU naturalnie mają małą rezystancję.','Brak ciągłości może wynikać z bezpiecznika, ścieżki, złącza lub błędnego punktu odniesienia.','Napięcie poza zakresem trzeba interpretować względem schematu, stanu zasilania i sekwencji startowej.'],tests:['Sprawdź, czy pomiar jest powtarzalny i wykonany na właściwym zakresie.','Po zakończeniu usuń sondy i sprawdź, czy nie pozostawiono zwarcia lub luźnych przewodów.','Zapisz wynik i dokumentację, na której oparto wniosek.'],mistakes:['Pomiar rezystancji na zasilonej płycie.','Pomiar prądu przez zwarcie sondami źródła napięcia.','Uznanie każdej niskiej rezystancji za zwarcie.','Użycie schematu podobnej, ale nie tej samej rewizji.'],safety:'Nie wykonuj pomiarów po stronie sieciowej zasilacza ani na odsłoniętych obwodach wysokiego napięcia. Pomiar napięć na płycie i próby zwarciowe są przeznaczone dla przeszkolonych techników.'},
    {id:'cpu',re:/procesor|\bcpu\b|intel core|ryzen|thermal throttling|rdzenie procesora/i,label:'Procesor CPU i testy stabilności',tools:['CPU-Z lub dokumentacja producenta do identyfikacji procesora','Intel Processor Diagnostic Tool dla obsługiwanych CPU Intel albo narzędzie diagnostyczne producenta','HWiNFO lub odpowiednik do monitorowania temperatur i taktowań (sprawdź licencję)','Sprawny układ chłodzenia i aktualny BIOS/UEFI zgodny z modelem','Notatnik do zapisu temperatur, taktowań, mocy i wyniku testu'],prep:['Zidentyfikuj dokładny model CPU, płytę, BIOS i system operacyjny.','Sprawdź chłodzenie, mocowanie radiatora, wentylatory i przepływ powietrza.','Przywróć ustawienia domyślne CPU; zapisz ewentualne OC/undervolting przed zmianami.','Zapisz temperaturę spoczynkową i zachowanie systemu bez obciążenia.'],steps:['Odczytaj model CPU i porównaj go z dokumentacją producenta.','Uruchom monitoring temperatur, taktowania i limitów termicznych przed testem.','Sprawdź błędy w Podglądzie zdarzeń i Monitorze niezawodności.','Dla obsługiwanego Intel CPU wykonaj Intel Processor Diagnostic Tool, zapisując raport PASS/FAIL.','Dopiero gdy chłodzenie jest sprawne, uruchom krótki, kontrolowany test obciążeniowy i obserwuj temperaturę.','Jeśli test wywołuje throttling, błąd, reset lub zbyt wysoką temperaturę, przerwij i sprawdź chłodzenie, zasilanie oraz ustawienia.'],solutions:['Błąd testu przy prawidłowej temperaturze — sprawdź ustawienia BIOS, pamięć i płytę; powtórz test według instrukcji narzędzia.','Wysoka temperatura i spadek taktowania — sprawdź docisk radiatora, wentylator, pastę/termopady i przepływ powietrza.','Niestabilność po OC/undervolting — wróć do ustawień fabrycznych i porównaj zachowanie.'],tests:['Wykonaj ponowny test w tych samych warunkach po naprawie.','Potwierdź brak throttlingu, resetów i błędów w logach.','Zapisz raport, temperatury i warunki testu; krótki test nie gwarantuje pełnej stabilności.'],mistakes:['Stress test przy niesprawnym chłodzeniu.','Uznanie samego wysokiego odczytu z programu za dowód uszkodzenia CPU.','Zmiana napięć i mnożnika bez planu i dokumentacji.','Brak zapisu ustawień przed aktualizacją BIOS lub resetem.'],safety:'Nie wykonuj długiego testu obciążeniowego przy nieznanym stanie chłodzenia. Nie zmieniaj napięć ani limitów zasilania bez znajomości modelu, specyfikacji i skutków dla gwarancji.'},
    {id:'power',re:/zasil|power|dc-in|ładow|charger|wejście|brak reakcji|nie włącza|nie startuje|standby|mosfet|przycisk start/i,label:'Zasilanie i sekwencja startowa',tools:['Oryginalny lub zatwierdzony zasilacz o właściwych parametrach','Multimetr i dokumentacja urządzenia','Testowany przewód i gniazdo sieciowe','Ochrona ESD i narzędzia izolowane','Tester zasilacza PC — zgodnie z instrukcją urządzenia'],prep:['Potwierdź napięcie, prąd/moc, polaryzację i identyfikację zasilacza.','Sprawdź gniazdko i przewód innym bezpiecznym urządzeniem.','Odłącz akcesoria, stację dokującą i niepotrzebne urządzenia USB.','Oceń, czy objaw to brak reakcji, krótki błysk diody, cykliczny start czy start bez obrazu.'],steps:['Zapisz reakcję LED, wentylatora, sygnałów dźwiękowych i przycisku Power.','Sprawdź adapter i gniazdo bez otwierania zasilacza sieciowego.','Porównaj działanie z zatwierdzonym, zgodnym zasilaczem.','W laptopie sprawdź komunikaty ładowania i zgodność USB-C PD, jeżeli dotyczy.','W naprawie płyty technik identyfikuje DC-IN, bezpiecznik, elementy przełączające i linie standby ze schematu.','Dalsze pomiary wykonuj tylko w znanych punktach i przy kontrolowanych warunkach.'],solutions:['Brak napięcia na wyjściu adaptera — zweryfikuj adapter i jego przewód na stanowisku testowym.','Napięcie wejściowe obecne, lecz brak czuwania — analizuj tor DC-IN i standby według schematu.','Start i natychmiastowe wyłączenie — zbierz kody POST i sprawdź, czy zadziałało zabezpieczenie; nie powtarzaj cykli bez diagnozy.'],tests:['Wykonaj zimny start i kilka kontrolowanych uruchomień.','Sprawdź stabilność zasilania, ładowanie i brak nadmiernego nagrzewania.','Potwierdź POST, obraz i stabilność po odłączeniu oraz ponownym podłączeniu zasilacza.'],mistakes:['Podłączenie zasilacza o niewłaściwym napięciu lub polaryzacji.','Wielokrotne próby uruchomienia płyty ze zwarciem.','Zwieranie bezpieczników drutem.','Otwieranie zasilacza ATX lub adaptera sieciowego.'],safety:'Nie otwieraj zasilacza sieciowego. Przy iskrzeniu, dymie, gorącym gnieździe lub śladach zalania natychmiast odłącz zasilanie i przerwij.'},
    {id:'bios',re:/bios|uefi|firmware|spi|programator|flash|ec\/kbc|kbc|nvram|cmos|rtc|boot|rozruch|post|boardview|schemat|płyta główna|mainboard/i,label:'Płyta główna, BIOS/UEFI i rozruch',tools:['Dokładny numer modelu i rewizja płyty','Schemat i BoardView zgodne z rewizją','Oficjalny plik firmware i instrukcja producenta','Nośnik USB przygotowany zgodnie z dokumentacją','Stabilne zasilanie; klucz BitLocker i kopia danych przed zmianą firmware'],prep:['Zapisz obecną wersję BIOS/UEFI i pełny model komputera/płyty.','Sprawdź, czy problem dotyczy POST, bootloadera, systemu czy samego firmware.','Zabezpiecz dane i odszukaj klucz odzyskiwania BitLocker.','Pobierz firmware wyłącznie z oficjalnego portalu dla dokładnego modelu.'],steps:['Zanotuj kody POST, diody debug i dokładny moment zatrzymania.','Sprawdź minimalną konfigurację zgodną z instrukcją płyty.','Zweryfikuj tryb UEFI/Legacy, Secure Boot, kolejność bootowania i wykrywanie nośnika — zapisując stan początkowy.','Reset CMOS wykonuj tylko według dokumentacji i po zabezpieczeniu klucza szyfrowania.','Aktualizuj BIOS tylko wtedy, gdy producent publikuje poprawkę dotyczącą danego objawu lub zgodności.','Przed programowaniem SPI wykonaj identyfikację układu i kopię oryginalnej zawartości; porównaj odczyty i zachowaj regiony specyficzne dla urządzenia.'],solutions:['Błędny tryb bootowania — porównaj ustawienia z konfiguracją dysku, nie przełączaj AHCI/RAID bez planu.','Brak obrazu i błąd DRAM/VGA — odczytaj kod POST, wyklucz RAM i tor obrazu przed diagnozą BIOS.','Nieudana aktualizacja — postępuj wyłącznie według procedury recovery producenta; nie zapisuj przypadkowego wsadu.'],tests:['Sprawdź, czy POST kończy się poprawnie i firmware widzi pamięć oraz dyski.','Potwierdź datę, godzinę, tryb bootowania i Secure Boot.','Uruchom system i sprawdź BitLocker, urządzenia oraz logi po aktualizacji.'],mistakes:['Flashowanie BIOS plikiem od podobnego modelu.','Brak kopii oryginalnego wsadu SPI.','Reset CMOS bez zabezpieczenia klucza BitLocker.','Przerwanie aktualizacji lub aktualizacja przy niestabilnym zasilaniu.'],safety:'Firmware, SPI i praca na płycie wymagają kwalifikacji i dokładnej dokumentacji. Nie programuj bez potwierdzenia układu, napięcia I/O i zgodności wsadu.'},
    {id:'ram',re:/ram|pamięć|memory|dram|sodimm|dimm|xmp|expo|post memory/i,label:'Pamięć RAM i testy stabilności',tools:['Instrukcja płyty/laptopa i lista kompatybilności pamięci','Memtest86+ lub MemTest86 z oficjalnej strony','Znany sprawny moduł zgodnego typu DDR','Ochrona ESD i aparat do dokumentacji slotów'],prep:['Sprawdź generację DDR, maksymalną pojemność i obsługiwane konfiguracje.','Zapisz ustawienia XMP/EXPO oraz częstotliwość i timingi.','Odłącz zasilanie przed wyjęciem modułu.','Ustal, czy błąd występuje zawsze, tylko pod obciążeniem czy po zmianie ustawień.'],steps:['Przywróć ustawienia pamięci do domyślnych JEDEC, jeżeli stabilność jest podejrzana.','Testuj jeden moduł w zalecanym slocie opisanym przez producenta.','Powtórz test tym samym modułem w innych dopuszczonych slotach.','Uruchom test UEFI RAM z oficjalnego nośnika, zapisz błędy i konfigurację.','Jeżeli błędy występują, izoluj moduł, slot i kontroler pamięci; nie zakładaj, że winny jest wyłącznie RAM.','Po zmianie ustawień lub sprzętu wykonaj pełny test i powtórz scenariusz usterki.'],solutions:['Błędy tylko z XMP/EXPO — sprawdź stabilność na ustawieniach domyślnych i zgodność zestawu.','Błąd jednego modułu w różnych slotach — podejrzenie modułu; potwierdź drugim testem.','Błąd różnych modułów w tym samym slocie — podejrzenie slotu, płyty lub kontrolera CPU.'],tests:['Wykonaj kilka pełnych przebiegów testu pamięci.','Po teście w Windows sprawdź Podgląd zdarzeń i stabilność aplikacji.','Zapisz liczbę błędów, adresy i konfigurację modułów.'],mistakes:['Testowanie jednocześnie wielu zmiennych.','Porównywanie DDR4 i DDR5 bez sprawdzenia kompatybilności.','Uznanie jednego krótkiego testu bez błędu za absolutną gwarancję.','Włączanie wysokiego profilu XMP/EXPO podczas diagnozy.'],safety:'Nie wkładaj ani nie wyjmuj RAM przy podłączonym zasilaniu. Stosuj ochronę ESD; nie dotykaj styków modułu.'},
    {id:'storage',re:/dysk|ssd|hdd|nvme|sata|smart|nośnik|partyc|bitlocker|odzyskiw|dane|plik/i,label:'Dyski, SMART i ochrona danych',tools:['Nośnik docelowy o wystarczającej pojemności do kopii/obrazu','Narzędzie SMART i oficjalne narzędzie producenta SSD/HDD','Adapter SATA/NVMe zgodny z protokołem i kluczem M.2','Zasilanie stabilne i przewody sprawdzone na znanym dobrym urządzeniu'],prep:['Najpierw ustal priorytet danych i uzyskaj zgodę na operacje.','Sprawdź, czy dysk klika, znika, zawiesza system lub zgłasza błędy odczytu.','Nie uruchamiaj długich testów obciążeniowych na nośniku z objawami awarii.','Zapisz model, firmware, temperaturę i parametry SMART/NVMe Health.'],steps:['Jeśli dane są ważne, wykonaj kopię lub obraz na zdrowy nośnik zanim zaczniesz naprawiać system plików.','Sprawdź przewód, port, zasilanie i zgodność interfejsu SATA/NVMe.','Odczytaj SMART i logi błędów; interpretuj parametry dla konkretnego modelu.','Uruchom krótki test producenta tylko wtedy, gdy stan nośnika na to pozwala.','Jeżeli występują błędy odczytu, klikanie lub znikanie, przerwij kolejne próby i rozważ profesjonalne obrazowanie.','Dopiero na kopii analizuj partycje i system plików.'],solutions:['Dysk nie wykrywa się w BIOS — sprawdź kompatybilność gniazda, tryb kontrolera, złącze i zasilanie.','SMART ostrzega, ale dysk działa — zrób kopię i porównaj logi; SMART nie gwarantuje przyszłej sprawności.','Uszkodzony system plików — pracuj na kopii; CHKDSK może modyfikować metadane i nie zastępuje odzysku danych.'],tests:['Po wymianie sprawdź SMART i firmware narzędziem producenta.','Wykonaj test odczytu/zapisu na pustym lub testowym nośniku, nie na jedynej kopii danych.','Potwierdź widoczność partycji, plików i poprawność kopii.'],mistakes:['Uruchamianie CHKDSK /r na dysku fizycznie umierającym przed obrazowaniem.','Zapisywanie danych na źródłowym nośniku do odzyskania.','Ignorowanie temperatury i błędów interfejsu.','Utożsamianie adaptera M.2 SATA z NVMe.'],safety:'Przy klikającym HDD, zapachu spalenizny, nagłym znikaniu lub ważnych danych przerwij testy i nie wykonuj zapisów na oryginale.'},
    {id:'gpu',re:/gpu|grafik|karta graficzna|vram|display driver|nvidia|radeon|intel arc|artefakt/i,label:'Karta graficzna i sterowniki GPU',tools:['Sprawdzony kabel i monitor z właściwym wejściem','Oficjalny sterownik Intel/AMD/NVIDIA lub OEM laptopa','Narzędzie monitorujące temperaturę i zegary','Test 3D o kontrolowanym obciążeniu; nie używaj go jako pierwszej próby','W znanym dobrym PC — kompatybilny zasilacz i slot PCIe'],prep:['Zapisz model GPU, wersję sterownika i moment wystąpienia artefaktów.','Sprawdź kabel, wejście monitora i inny ekran.','Obejrzyj zasilanie GPU i osadzenie karty przy odłączonym zasilaniu.','Nie zmieniaj jednocześnie sterownika, BIOS i ustawień OC.'],steps:['Sprawdź, czy artefakty są obecne już w BIOS/POST, czy dopiero w Windows lub grze.','Porównaj inny kabel, port i monitor.','Przy problemie sterownika pobierz właściwy pakiet z oficjalnej strony producenta lub OEM.','Wykonaj czystą instalację tylko przy uzasadnieniu i według instrukcji producenta.','Monitoruj temperatury, hotspot, zegary, pobór mocy i wentylatory podczas krótkiego kontrolowanego testu.','Jeżeli artefakty pozostają poza systemem lub występują błędy VRAM, wykonaj test krzyżowy na znanym dobrym sprzęcie.'],solutions:['Artefakty tylko po sterowniku/gry — sprawdź wersję sterownika, ustawienia aplikacji i logi.','Artefakty przed startem systemu — podejrzenie sprzętu, kabla/monitora lub firmware; testuj tor obrazu.','Reset sterownika pod obciążeniem — monitoruj temperaturę, zasilanie i błędy systemowe.'],tests:['Powtórz test w tych samych ustawieniach i czasie.','Sprawdź kilka wyjść obrazu i brak artefaktów.','Zapisz temperaturę rdzenia/hotspot, zegary i wersję sterownika.'],mistakes:['Wymiana karty bez sprawdzenia kabla i monitora.','Długi test obciążeniowy przy rosnącej temperaturze lub zapachu.','Mieszanie sterowników z przypadkowych stron.','Wgranie VBIOS od innego producenta/modelu.'],safety:'Przerwij test przy artefaktach nasilających się, niestabilnym zasilaniu, dymie lub nienormalnym nagrzewaniu. Nie wykonuj reflow jako uniwersalnej naprawy.'},
    {id:'display',re:/ekran|matryc|wyświetl|podświetl|eDP|lvds|taśm|zawias|monitor|hdmi|displayport|usb-c.*obraz/i,label:'Obraz, matryca i tor wyświetlania',tools:['Zewnętrzny monitor i sprawdzony kabel','Latarka do testu obrazu (bez nacisku na panel)','Dokładna instrukcja serwisowa i kompatybilny panel','Narzędzia plastikowe i ochrona ESD'],prep:['Zapisz, czy laptop daje dźwięk/POST i czy obraz pojawia się na zewnętrznym monitorze.','Sprawdź jasność, skrót przełączania ekranu i wybrane wejście monitora.','Wyłącz urządzenie i odłącz baterię zgodnie z instrukcją przed pracą przy złączu eDP/LVDS.'],steps:['Sprawdź zewnętrzny monitor i kabel, aby oddzielić problem GPU od matrycy.','Oświetl panel latarką pod kątem; słabo widoczny obraz może wskazywać na problem podświetlenia, ale wymaga dalszego potwierdzenia.','Obejrzyj zawiasy, ramkę i ślady nacisku.','Sprawdź taśmę i złącza tylko po odłączeniu zasilania i baterii.','Porównaj numer części, rozdzielczość, złącze i parametry panelu przed wymianą.'],solutions:['Obraz działa na monitorze, a panel jest czarny — diagnozuj panel, taśmę i podświetlenie.','Brak obrazu także na monitorze — sprawdź POST, RAM, GPU i firmware.','Migotanie przy ruchu pokrywy — podejrzenie taśmy/zawiasu; ogranicz ruch i sprawdź mechanikę.'],tests:['Wykonaj test jasności, kolorów, rozdzielczości i odświeżania.','Porusz delikatnie pokrywą, obserwując czy obraz nie zanika.','Sprawdź zewnętrzne wyjścia i brak zwarć lub uszkodzenia taśmy.'],mistakes:['Wymiana panelu bez sprawdzenia kabla i sygnału.','Podłączanie/odłączanie eDP przy zasilaniu.','Zakup matrycy tylko na podstawie przekątnej.'],safety:'Nigdy nie podłączaj taśmy matrycy pod napięciem. Pęknięte szkło i uszkodzony panel wymagają ochrony przed skaleczeniem.'},
    {id:'cooling',re:/chłod|temperatur|wentyl|pasta|termopad|heatpipe|throttl|fan|radiator/i,label:'Chłodzenie, temperatury i hałas',tools:['Monitor temperatur i obrotów kompatybilny z platformą','Sprężone powietrze lub gruszka oraz miękki pędzel','IPA i bezpyłowe materiały czyszczące zgodne z urządzeniem','Pasta i termopady o specyfikacji producenta','Śrubokręty i instrukcja demontażu chłodzenia'],prep:['Zapisz temperatury spoczynkowe i warunki pomiaru.','Sprawdź przepływ powietrza, profile wentylatorów i obciążenie CPU/GPU.','Odłącz zasilanie i baterię przed czyszczeniem wnętrza.','Zidentyfikuj grubość i rozmieszczenie padów — nie zakładaj uniwersalnej grubości.'],steps:['Oczyść wloty/wyloty i sprawdź, czy wentylator obraca się bez ocierania.','Sprawdź, czy radiator i heatpipe nie są zatkane lub poluzowane.','Jeżeli demontujesz chłodzenie, dokumentuj długości śrub i kolejność docisku.','Usuń starą pastę bez zalewania elementów; stosuj materiały właściwe dla modelu.','Wymieniaj termopady tylko na identyczną grubość/specyfikację wskazaną dla konkretnego układu.','Po montażu sprawdź RPM, temperatury, throttling i zachowanie przy kontrolowanym obciążeniu.'],solutions:['Wysoka temperatura i niski RPM — sprawdź wentylator, złącze i sterowanie.','Wysoka temperatura po serwisie — sprawdź docisk, kolejność śrub, folie ochronne i termopady.','Nagłe wyłączanie — nie powtarzaj testów; wyklucz chłodzenie i zasilanie.'],tests:['Porównaj temperatury przed/po w identycznych warunkach i obciążeniu.','Sprawdź, czy nie pojawia się throttling lub hałas łożyska.','Wykonaj test stabilności z monitorowaniem, zaczynając krótko i stopniowo.'],mistakes:['Zbyt grube termopady unoszące radiator.','Blokowanie wentylatora palcem podczas przedmuchiwania.','Długi stress test bez monitorowania.','Używanie pasty zamiast termopadu bez specyfikacji.'],safety:'Nie używaj sprężonego powietrza tak, aby rozkręcić wentylator do bardzo wysokich obrotów. Przerwij przy zapachu spalenizny, dymie lub wyłączaniu termicznym.'},
    {id:'windows',re:/windows|system|sterownik|update|aktualiz|sfc|dism|chkdsk|boot|rozruch|bsod|bitlocker|malware|wirus|bezpieczeństwo systemu/i,label:'Windows, sterowniki i bezpieczeństwo',tools:['Kopia danych i klucz BitLocker','Podgląd zdarzeń oraz Monitor niezawodności','Menedżer urządzeń i Windows Update','Nośnik instalacyjny/recovery z oficjalnego źródła','Notatnik z kodami błędów i zmianami wykonanymi podczas diagnozy'],prep:['Zapisz numer kompilacji, edycję Windows i dokładny kod błędu.','Sprawdź, czy problem pojawił się po aktualizacji/sterowniku/aplikacji.','Sprawdź zdrowie dysku i kopię danych przed naprawą systemu plików.','Upewnij się, że znasz klucz BitLocker przed zmianą firmware lub recovery.'],steps:['Zbierz komunikaty, datę, kod stop i wpisy w Podglądzie zdarzeń.','Sprawdź Menedżer urządzeń i historię aktualizacji.','Przetestuj tryb awaryjny lub czysty rozruch, aby odseparować sterownik/usługę.','Przy podejrzeniu uszkodzenia plików systemowych postępuj według Microsoft: DISM /Online /Cleanup-Image /RestoreHealth, potem sfc /scannow.','Dla błędów rozruchu użyj najpierw WinRE/Startup Repair, nie edytuj BCD bez kopii i zrozumienia konfiguracji.','Dopiero po kopii i wykluczeniu awarii dysku rozważ CHKDSK lub reset/reinstalację.'],solutions:['Problem po sterowniku — rozważ przywrócenie poprzedniej wersji zgodnie z dokumentacją Microsoft/OEM.','Błędy SFC — wykonaj DISM i ponownie SFC zgodnie z instrukcją.','Problem po aktualizacji — użyj oficjalnego troubleshootera lub WinRE do odinstalowania konkretnej aktualizacji, jeśli jest to wskazane.'],tests:['Uruchom ponownie komputer i powtórz scenariusz, który wcześniej powodował błąd.','Sprawdź Podgląd zdarzeń, aktualizacje i stan urządzeń.','Sprawdź, czy kopia, szyfrowanie i zabezpieczenia nadal działają.'],mistakes:['Reinstalacja systemu przed zabezpieczeniem danych.','Uruchamianie CHKDSK na fizycznie uszkodzonym dysku bez obrazu.','Użycie sterowników z nieoficjalnych agregatorów.','Wyłączenie ochrony antywirusowej jako uniwersalna metoda naprawy.'],safety:'Nie wyłączaj antywirusa ani zapory, aby instalować niezweryfikowane narzędzia. W sprawach malware zachowaj dowody i używaj zaufanego skanera, także trybu offline z uwzględnieniem BitLocker.'},
    {id:'network',re:/wi-?fi|wifi|ethernet|lan|router|sieć|dns|bluetooth|ip|dhcp|internet/i,label:'Sieć, Wi-Fi i router',tools:['Drugi komputer/telefon jako urządzenie porównawcze','Sprawdzony przewód Ethernet','Ustawienia routera i dokumentacja producenta','Polecenia diagnostyczne Windows: ipconfig, ping, nslookup, tracert','Dostęp do panelu routera i aktualny firmware z oficjalnej strony'],prep:['Zapisz dokładny komunikat błędu i czy problem dotyczy jednego urządzenia, czy wszystkich.','Nie resetuj routera do fabrycznych bez zapisania konfiguracji i danych dostępu.','Sprawdź, czy usługa operatora działa i czy nie ma awarii po jego stronie.'],steps:['Sprawdź fizyczne połączenie, diody linku, kabel i port.','Uruchom ipconfig /all i zapisz adres IP, bramę i DNS.','Pinguj najpierw własną bramę, a następnie znany publiczny adres IP.','Użyj nslookup do oddzielenia problemu DNS od braku łączności IP.','Porównaj inne urządzenie i inną sieć, aby wykluczyć komputer/router/operatora.','Firmware routera aktualizuj wyłącznie dla dokładnego modelu i rewizji z oficjalnego źródła.'],solutions:['Brak adresu/brama 169.254.x.x — sprawdź DHCP i połączenie do routera.','Ping do bramy działa, DNS nie — sprawdź resolver, konfigurację DNS i profil sieci.','Wszystkie urządzenia tracą internet — sprawdź WAN/router i komunikaty operatora.'],tests:['Sprawdź ping do bramy, rozwiązywanie DNS i dostęp do kilku usług.','Powtórz test na Ethernet/Wi-Fi oraz na drugim urządzeniu.','Po zmianie routera sprawdź bezpieczeństwo Wi-Fi, WPA2-AES/WPA3, aktualność firmware i hasło administratora.'],mistakes:['Reset routera bez kopii ustawień.','Zmiana kilku ustawień DNS/DHCP naraz.','Wgranie firmware z innej rewizji urządzenia.','Ujawnianie hasła administratora routera lub danych sieciowych w czacie.'],safety:'Nie skanuj sieci, których nie jesteś właścicielem lub do których nie masz upoważnienia. Nie publikuj haseł, kluczy Wi-Fi, adresów publicznych ani danych logowania.'},
    {id:'peripherals',re:/klawiatur|touchpad|kamera|mikrofon|audio|dźwięk|głośnik|bluetooth|usb|port|drukark|dock|stacja dokując/i,label:'Porty, urządzenia i peryferia',tools:['Drugie sprawne urządzenie peryferyjne','Drugi przewód/adaptor zgodny z wymaganym standardem','Menedżer urządzeń i ustawienia prywatności Windows','Instrukcja portu i stacji dokującej'],prep:['Ustal, czy problem dotyczy jednego urządzenia czy portu.','Sprawdź uprawnienia systemowe, poziom baterii akcesorium i fizyczny stan złącza.','Nie wciskaj wtyku na siłę i nie testuj luźnego/wyłamanego portu pod obciążeniem.'],steps:['Porównaj urządzenie na drugim komputerze i inny sprawny osprzęt na badanym komputerze.','Sprawdź Menedżer urządzeń, kody błędów i historię sterownika.','Zweryfikuj ustawienia prywatności mikrofonu/kamery oraz domyślne wejście/wyjście audio.','Dla USB-C sprawdź, czy port obsługuje wymagane dane, DisplayPort Alt Mode i Power Delivery.','Zaktualizuj sterownik tylko ze sprawdzonego źródła OEM/producenta.','Sprawdź złącze wizualnie i mechanicznie po odłączeniu zasilania.'],solutions:['Urządzenie działa na innym PC — sprawdź sterownik, port i uprawnienia badanego systemu.','USB-C ładuje, ale nie wyświetla obrazu — port może nie mieć DP Alt Mode; potwierdź specyfikację.','Brak kamery/mikrofonu w aplikacji — sprawdź przesłonę, prywatność i wybrane urządzenie.'],tests:['Wykonaj kilka połączeń/odłączeń oraz sprawdź stabilność bez poruszania portem.','Sprawdź transfer, obraz, ładowanie lub audio zgodnie z funkcją portu.','Zapisz kompatybilność przewodu, portu i urządzenia.'],mistakes:['Uznanie, że każdy port USB-C przenosi obraz.','Usuwanie sterowników chipsetu ręcznie bez instrukcji OEM.','Pomijanie ustawień prywatności i domyślnego audio.'],safety:'Nie używaj metalowych narzędzi do czyszczenia zasilonego portu. Przy wyłamanym lub nadpalonym porcie przerwij używanie i wykonaj inspekcję serwisową.'},
    {id:'battery',re:/bater|akumulator|lithium|li-ion|spuch|ładow/i,label:'Bateria i układ ładowania',tools:['Oryginalny lub zgodny zasilacz o parametrach producenta','Diagnostyka baterii/raport producenta','Ochrona oczu i rękawice dobrane do procedury serwisowej','Pojemnik i procedura bezpiecznego postępowania z uszkodzonym ogniwem'],prep:['Sprawdź, czy bateria nie jest spuchnięta, zdeformowana, gorąca lub uszkodzona.','Zapisz model baterii, napięcie nominalne, pojemność i oznaczenia.','Porównaj zasilacz i ładowanie z dokumentacją urządzenia.'],steps:['Jeśli bateria jest spuchnięta lub uszkodzona, przerwij używanie i nie ładuj jej.','Odłącz zasilacz i postępuj według procedury producenta; nie naciskaj ani nie przebijaj ogniwa.','Dla baterii bez widocznych uszkodzeń odczytaj raport kondycji i liczbę cykli, jeśli jest dostępna.','Sprawdź zgodność adaptera, portu i protokołu ładowania (np. USB-C PD).','Dalszą diagnostykę układu ładowania wykonuje technik na podstawie schematu i specyfikacji kontrolera.'],solutions:['Brak ładowania z jednym adapterem — porównaj zgodny zasilacz i kabel.','Bateria szybko się rozładowuje — porównaj zużycie, temperaturę i obciążenie systemu.','Spuchnięta bateria — wymiana i bezpieczna utylizacja; nie próbuj jej prostować ani ponownie używać.'],tests:['Po wymianie sprawdź poprawność wykrycia baterii i ładowania.','Obserwuj temperaturę i raport kondycji.','Sprawdź pracę z zasilacza i baterii przy umiarkowanym obciążeniu.'],mistakes:['Dalsze ładowanie spuchniętej baterii.','Przebijanie, zgniatanie lub wyginanie ogniwa.','Montaż zamiennika o niezgodnym napięciu/identyfikacji.'],safety:'Nie używaj i nie ładuj spuchniętej, przebitej, gorącej ani wydzielającej zapach baterii. Nie wykonuj samodzielnego demontażu ogniwa, jeśli nie masz procedur i przeszkolenia.'}
  ];
  const fallback = profileDefs[0];
  const profileFor = item => {
    const t = [item.title,item.category,item.description,item.body,item.symptoms,item.diagnosis,item.repair,item.tags].filter(Boolean).join(' ');
    return profileDefs.find(p=>p.re.test(t)) || fallback;
  };
  // Warstwa dydaktyczna: objaśnienie i schemat są dobierane do kategorii konkretnej lekcji.
  const teachingProfiles = {
    safety:{explain:'Wyładowanie elektrostatyczne (ESD) może uszkodzić wrażliwe wejścia półprzewodników, nawet jeśli człowiek go nie poczuje. Mata i opaska mają wyrównać potencjał technika, części i stanowiska. ESD nie chroni przed porażeniem napięciem sieciowym. Przed otwarciem komputera odłącz zasilacz, a baterię odłącz zgodnie z instrukcją modelu.',flow:['Zapisz objaw i model sprzętu','Odłącz zasilacz i baterię','Wyrównaj potencjał ESD','Wykonaj oględziny i demontaż','Złóż według dokumentacji','Sprawdź wszystkie funkcje'],first:'Najpierw ustal dokładny model i odłącz wszystkie źródła energii zgodnie z instrukcją serwisową.'},
    meter:{explain:'Multimetr mierzy różne wielkości, ale tryb i sposób podłączenia sondy są różne. Napięcie DC mierzy się równolegle, a prąd włącza szeregowo w obwód zgodnie z instrukcją miernika. Rezystancję i ciągłość mierzy się wyłącznie na odłączonym, bezpiecznie rozładowanym układzie. Wynik ma sens dopiero w odniesieniu do schematu i rewizji płyty.',flow:['Zidentyfikuj model i rewizję','Otwórz schemat i znajdź GND','Ustaw właściwy tryb miernika','Wykonaj kontrolowany pomiar','Porównaj ze specyfikacją','Zapisz wynik i potwierdź test'],first:'Odczytaj model i rewizję PCB, a następnie znajdź właściwy punkt GND w schemacie.'},
    cpu:{explain:'Procesor wykonuje instrukcje i współpracuje z pamięcią, chipsetem oraz układem zasilania. Temperatura, taktowanie i pobór mocy zmieniają się dynamicznie; sam odczyt z programu nie przesądza o uszkodzeniu. Diagnostyka zaczyna się od identyfikacji CPU, sprawdzenia chłodzenia i ustawień fabrycznych, a dopiero potem obejmuje test funkcjonalny lub krótkie obciążenie.',flow:['Zidentyfikuj CPU i płytę','Sprawdź chłodzenie i BIOS','Monitoruj temperatury i zegary','Uruchom test diagnostyczny','Porównaj błędy i logi','Powtórz test po korekcie'],first:'Najpierw odczytaj dokładny model CPU, BIOS i temperaturę w spoczynku.'},
    power:{explain:'Tor zasilania prowadzi od adaptera lub zasilacza przez gniazdo, ochronę wejścia, kontroler i przetwornice do linii zasilających. Kolejność uruchamiania zależy od platformy i kontrolera EC/PMIC. Wartości 3,3 V, 5 V czy 12 V są częste, ale nie stanowią uniwersalnego pinoutu ani potwierdzenia, że dana linia musi występować w każdej fazie.',flow:['Potwierdź zasilacz i model','Oceń objaw i kontrolki','Sprawdź wejście DC i ochronę','Analizuj standby wg schematu','Potwierdź sekwencję startową','Wykonaj zimny start i retest'],first:'Zacznij od zgodności adaptera, przewodu, gniazda i dokładnego objawu startu.'},
    bios:{explain:'UEFI/BIOS inicjalizuje urządzenia, wykonuje POST i przekazuje sterowanie menedżerowi rozruchu. CMOS/RTC przechowuje część ustawień, ale nie jest tym samym co kość firmware SPI. Aktualizacja firmware jest zależna od modelu i rewizji. Zmiany mogą uruchomić odzyskiwanie BitLocker, dlatego wcześniej zabezpiecz dane i klucz odzyskiwania.',flow:['Odczytaj model i rewizję','Zapisz wersję UEFI i ustawienia','Sprawdź POST oraz boot path','Zweryfikuj firmware OEM','Zabezpiecz BitLocker i zasilanie','Aktualizuj tylko wg instrukcji'],first:'Zapisz dokładny model, rewizję, obecną wersję BIOS i stan BitLocker.'},
    ram:{explain:'RAM jest pamięcią ulotną. Kontroler pamięci znajduje się w CPU, a ścieżki, gniazda, profile XMP/EXPO i moduły wpływają na stabilność. Błąd testu trzeba odseparować od konkretnej kości, gniazda, ustawień i kontrolera. Jeden przebieg bez błędów nie daje absolutnej gwarancji sprawności.',flow:['Zapisz obsadę i ustawienia','Przywróć ustawienia JEDEC','Testuj pojedynczy moduł','Zmień gniazdo i powtórz','Porównaj błędy i SPD','Zatwierdź stabilną konfigurację'],first:'Zapisz liczbę, model i rozmieszczenie modułów RAM, a następnie wyłącz profil OC pamięci.'},
    storage:{explain:'SSD SATA, SSD NVMe i HDD korzystają z różnych interfejsów i zachowują się inaczej. SMART dostarcza wskaźników kondycji, ale status „OK” nie gwarantuje, że nośnik nie ulegnie awarii. Przy niestabilnym nośniku priorytetem jest zabezpieczenie danych lub obraz sektorowy; naprawa systemu plików może zwiększyć obciążenie i utrudnić odzyskiwanie.',flow:['Zidentyfikuj nośnik i interfejs','Odczytaj SMART i logi','Oceń ryzyko utraty danych','Wykonaj kopię lub obraz','Diagnozuj na kopii / narzędziu OEM','Zweryfikuj dane i stabilność'],first:'Zanim uruchomisz naprawę, oceń stan nośnika i ważność danych; przy oznakach awarii najpierw zabezpiecz dane.'},
    gpu:{explain:'Obraz może przechodzić przez iGPU, dGPU, przełącznik MUX, układ retimera, kabel i matrycę lub wyjście zewnętrzne. Artefakty, brak obrazu i awarie sterownika to różne objawy. Trzeba rozdzielić problem sprzętowy od sterownika, temperatury, zasilania, przewodu i monitora.',flow:['Zapisz objaw i model GPU','Sprawdź przewód i monitor','Odczytaj sterownik i logi','Sprawdź temperatury i zasilanie','Testuj w kontrolowanym trybie','Potwierdź obraz i stabilność'],first:'Sprawdź, czy problem występuje na innym kablu, wejściu i monitorze, zanim uznasz GPU za uszkodzone.'},
    display:{explain:'Tor obrazu obejmuje GPU, wyjście sygnału, przewód eDP/LVDS lub HDMI/DP, złącza, matrycę i podświetlenie. Obraz na monitorze zewnętrznym oraz latarkowy test ekranu pomagają rozdzielić źródło problemu, ale wynik zależy od konstrukcji laptopa i jego dokumentacji.',flow:['Ustal model panelu i objaw','Sprawdź jasność i wejście','Porównaj obraz zewnętrzny','Sprawdź kabel i złącza','Oceń panel i podświetlenie','Wykonaj test obrazu po naprawie'],first:'Porównaj obraz na wbudowanej matrycy i monitorze zewnętrznym oraz zapisz, kiedy objaw występuje.'},
    cooling:{explain:'Ciepło jest przekazywane z CPU/GPU przez materiał termiczny do radiatora, komory parowej lub heatpipe, a następnie oddawane przez przepływ powietrza. Kurz, zużyty wentylator, nieprawidłowy docisk i niewłaściwa grubość termopadu mogą pogorszyć chłodzenie. Limity temperatur zależą od konkretnego układu.',flow:['Zapisz temperatury i obciążenie','Sprawdź wloty i wentylatory','Oczyść układ wg instrukcji','Oceń docisk i materiały TIM','Monitoruj temperaturę pod testem','Potwierdź brak throttlingu'],first:'Zmierz temperaturę w spoczynku i pod umiarkowanym obciążeniem, zapisując model CPU/GPU.'},
    windows:{explain:'Rozruch Windows przechodzi przez firmware UEFI, Windows Boot Manager, loader i jądro systemu. WinRE może uruchomić narzędzia naprawcze. SFC sprawdza chronione pliki systemowe, a DISM obsługuje obraz i magazyn składników. Przed zmianami boot/szyfrowania zapisz dane i przygotuj klucz BitLocker.',flow:['Zapisz komunikat i kod','Sprawdź UEFI i dysk','Uruchom właściwe WinRE','Zastosuj DISM / SFC wg objawu','Sprawdź logi i boot entries','Powtórz start i test funkcji'],first:'Zapisz kod błędu i etap, na którym zatrzymuje się start; nie formatuj dysku przed kopią danych.'},
    network:{explain:'Komputer łączy się z punktem dostępowym, uzyskuje parametry IP przez DHCP, a nazwy domen są zamieniane na adresy przez DNS. Router przekazuje ruch do sieci operatora. Test bramy, adresu IP, DNS i drugiego urządzenia pozwala ustalić, czy problem leży w komputerze, routerze czy u operatora.',flow:['Ustal zakres problemu','Sprawdź kabel / Wi-Fi / link','Odczytaj IP, bramę i DHCP','Testuj bramę i adres IP','Sprawdź DNS i WAN','Zabezpiecz router i zweryfikuj'],first:'Ustal, czy awaria dotyczy jednego komputera, wszystkich urządzeń czy tylko jednej usługi.'},
    peripherals:{explain:'Urządzenie peryferyjne wymaga zgodnego portu, kontrolera, sterownika, kabla i uprawnień systemowych. USB-C opisuje kształt złącza, a nie pełen zestaw funkcji: obraz, prędkość danych i ładowanie zależą od portu oraz przewodu. Kamera i mikrofon mogą działać sprzętowo, ale być zablokowane przez prywatność Windows.',flow:['Zidentyfikuj port i urządzenie','Sprawdź przewód i drugi komputer','Odczytaj Menedżer urządzeń','Sprawdź sterownik i uprawnienia','Zweryfikuj funkcję portu','Powtórz test pod obciążeniem'],first:'Sprawdź urządzenie z innym przewodem i komputerem, aby oddzielić usterkę akcesorium od portu.'},
    battery:{explain:'Pakiet Li-ion zawiera ogniwa i elektronikę BMS, która monitoruje temperaturę, napięcia i prąd. Układ ładowania współpracuje z adapterem, portem i płytą główną. Spuchnięcie, zapach, nadmierne ciepło lub uszkodzenie mechaniczne oznaczają przerwanie pracy — nie wolno takiej baterii ładować, zgniatać ani przebijać.',flow:['Oceń deformację i temperaturę','Przerwij przy uszkodzeniu baterii','Sprawdź adapter i protokół','Odczytaj raport kondycji','Zweryfikuj zgodność części','Przetestuj ładowanie i temperaturę'],first:'Najpierw sprawdź, czy bateria jest spuchnięta, gorąca lub uszkodzona; w takim przypadku przerwij używanie i ładowanie.'}
  };
  const teachingFor = p => teachingProfiles[p.id] || {explain:'Rozpoznaj funkcję podzespołu, ustal dokładny model oraz sprawdź jego dokumentację. Jeden test powinien weryfikować jedną hipotezę, a wynik trzeba zapisać.',flow:['Zapisz objaw i model','Zbierz dokumentację','Wybierz bezpieczny test','Porównaj wynik','Wprowadź uzasadnioną zmianę','Powtórz test'],first:'Zacznij od dokładnej identyfikacji urządzenia i objawu.'};
  const renderFlowChart = context => {
    const p=context.profile, teach=context.teaching;
    const nodes=teach.flow.map((label,i)=>`<div class="az-flow-node"><span>${String(i+1).padStart(2,'0')}</span><b>${esc(label)}</b></div>`).join('');
    return `<figure class="az-flow-figure"><figcaption><span class="eyebrow">SCHEMAT DIAGNOSTYKI DLA TEJ LEKCJI</span><b>${esc(context.title)}</b><small>${esc(p.label)} · prowadź testy od lewej do prawej, zapisując wynik każdego etapu</small></figcaption><div class="az-flow-grid">${nodes}</div><div class="az-flow-decision"><div><b>Wynik zgodny ze specyfikacją</b><span>Przejdź do testu końcowego i potwierdź pierwotny objaw.</span></div><div><b>Wynik niezgodny / niejednoznaczny</b><span>Przerwij eskalację, wróć do hipotezy, sprawdź dokumentację i nie wymieniaj części na ślepo.</span></div></div></figure>`;
  };

  const sourceMatches = p => sources.filter(s=>s.tags.some(tag=>p.id==='windows'?['windows','boot','recovery','system','drivers','update','security'].includes(tag):p.id==='storage'?['disk','ssd','hdd','smart','bitlocker','data'].includes(tag):p.id==='ram'?['ram','memory','diagnostics'].includes(tag):p.id==='bios'?['bios','uefi','firmware','oem','diagnostics'].includes(tag):p.id==='meter'?['esd','safety','electronics'].includes(tag):p.id==='safety'?['esd','safety','battery'].includes(tag):p.id==='power'||p.id==='battery'?['battery','safety','oem'].includes(tag):p.id==='cpu'?['cpu','intel','monitoring','diagnostics','stress'].includes(tag):p.id==='gpu'?['gpu','drivers','intel','amd','nvidia','monitoring'].includes(tag):p.id==='network'?['network','drivers','oem','router','wifi','security','cybersecurity'].includes(tag):p.id==='peripherals'?['peripherals','camera','microphone','windows','drivers','oem'].includes(tag):p.id==='cooling'?['safety','oem','cpu','monitoring'].includes(tag):p.id==='display'?['oem','drivers','gpu'].includes(tag):['drivers','oem','diagnostics'].includes(tag))).slice(0,7);
  const asList = value => {
    if(Array.isArray(value)) return value;
    if(!value) return [];
    return String(value).split(/\n+/).map(x=>x.replace(/^\s*(?:[•·\-]|\d+[.)])\s*/, '').trim()).filter(Boolean);
  };
  let ctx = null;
  const createContext = (item,tab) => {
    const profile=profileFor(item);
    const teaching=teachingFor(profile);
    const description=item.body||item.description||item.symptoms||item.diagnosis||'Temat wymaga pracy według dokumentacji konkretnego modelu.';
    const originalSteps=asList(item.steps).length?asList(item.steps):asList(item.guides?.map(g=>g.title+' — '+g.body).join('\n'));
    const diagnosis=item.diagnosis||item.checks||item.symptoms||'';
    const repairs=item.repair||item.steps||'';
    const sourcesFor=sourceMatches(profile);
    const key=(item.id||item.title||'lesson')+':'+tab;
    return {item,tab,profile,teaching,title:item.title||'Lekcja',description,diagnosis,repairs,originalSteps,sources:sourcesFor,key};
  };
  const chatHtml = context => {
    ctx=context;
    const p=context.profile;
    return `<section class="lesson-tutor" aria-label="Czat pomocnika tej lekcji"><div class="tutor-head"><div><span class="eyebrow">POMOCNIK TEJ LEKCJI</span><h3>Zapytaj o: ${esc(context.title)}</h3><p>Odpowiedzi są dopasowane do tej lekcji: wyjaśniają pojęcia, kolejność testów, rozwiązania i źródła producentów.</p></div><span class="tutor-local-badge">LOKALNY CZAT</span></div><div class="tutor-messages" id="tutorMessages" role="log" aria-live="polite"><div class="tutor-message tutor-bot"><b>Pomocnik Akademii</b><p>Jestem przypisany do tej lekcji. Mogę wyjaśnić pojęcia, rozpisać diagnozę, omówić rozwiązania i wskazać oficjalne materiały producentów. Zacznij od pytania lub wybierz podpowiedź.</p></div></div><div class="tutor-prompts"><button type="button" data-tutor-prompt="Wyjaśnij temat od podstaw, prostym językiem.">Wyjaśnij od podstaw</button><button type="button" data-tutor-prompt="Pokaż bezpieczną diagnostykę krok po kroku.">Kroki diagnozy</button><button type="button" data-tutor-prompt="Jak rozpoznać przyczynę i jakie są rozwiązania?">Możliwe rozwiązania</button><button type="button" data-tutor-prompt="Jak sprawdzić wynik i wykonać test po naprawie?">Test końcowy</button><button type="button" data-tutor-prompt="Pokaż najnowsze oficjalne źródła i narzędzia do tego tematu.">Najnowsze źródła</button></div><form class="tutor-form" id="tutorChatForm"><input id="tutorQuestion" type="text" maxlength="500" placeholder="Napisz pytanie o tę lekcję…" autocomplete="off" required><button class="btn btn-primary btn-small" type="submit">Wyślij pytanie</button></form><div class="tutor-disclaimer">Pomocnik działa lokalnie według scenariuszy i danych tej lekcji — nie jest generatywnym ChatGPT i nie wyszukuje Internetu na żywo. Nie wpisuj haseł, kluczy BitLocker, numerów seryjnych ani danych klienta. Najnowsze daty i wersje sprawdzaj w podlinkowanych stronach producenta.</div></section>`;
  };
  // 17 dodatkowych etapów J-Z. Treść jest wiązana z konkretnym tematem,
  // profilem sprzętowym, objawem i materiałem źródłowym bieżącej lekcji.
  const alphabetStages = c => {
    const p=c.profile, i=c.item, title=c.title, desc=c.description;
    const symptom=i.symptoms||i.diagnosis||desc;
    const stages=[
      ['J','Rejestracja objawu i warunków','Zapisz dokładny komunikat, kod błędu, moment wystąpienia, czas do awarii i to, czy problem jest stały czy losowy.',`Objaw w tej lekcji: ${symptom}`,['Nie zmieniaj ustawień przed zapisaniem stanu początkowego.','Zrób zdjęcie komunikatu lub zrzut ekranu bez ujawniania danych klienta.','Zapisz temperaturę, obciążenie i podłączone urządzenia, jeśli mają znaczenie.']],
      ['K','Identyfikacja urządzenia i zgodności','Ustal pełny model komputera, płyty, podzespołu, rewizję PCB, identyfikator urządzenia i wersję firmware.',`Zakres tej lekcji: ${p.label}. Nie stosuj schematu ani BIOS-u dla podobnej, ale innej rewizji.`,['Sprawdź oznaczenie z etykiety i BIOS/UEFI.','W razie potrzeby odczytaj identyfikator PCI/USB i numer części.','Porównaj parametry z oficjalną dokumentacją producenta.']],
      ['L','Historia zmian i odtwarzalność','Ustal, co zmieniło się przed awarią: aktualizacja, upadek, zalanie, wymiana RAM/SSD, zmiana ustawień, nowy sterownik lub program.',`Zapisz historię dotyczącą „${title}” i oddziel korelację czasową od potwierdzonej przyczyny.`,['Zapytaj o ostatnie działające uruchomienie.','Sprawdź historię aktualizacji i instalacji.','Nie cofaj wielu zmian jednocześnie — testuj pojedynczo.']],
      ['M','Pomiary, odczyty i wartości odniesienia','Dobierz tylko pomiary adekwatne do tej usterki. Zapisz jednostkę, zakres, warunki, punkt pomiarowy i źródło wartości referencyjnej.',`W obszarze ${p.label}: ${c.teaching.explain}`,p.id==='meter'?['Najpierw identyfikuj punkt i masę w schemacie dokładnej rewizji.','Rezystancję i ciągłość mierz tylko po odłączeniu źródeł energii i bezpiecznym rozładowaniu.','Napięcie mierz właściwym zakresem i bez zwierania sąsiednich pinów.']:['Zapisz parametry przed zmianą i po niej.','Porównaj wynik z oficjalną specyfikacją albo znanym dobrym urządzeniem.','Nie traktuj pojedynczego odczytu z programu jako dowodu uszkodzenia.']],
      ['N','Logi, kody POST i diagnostyka systemowa','Zbierz komunikaty firmware, Menedżera urządzeń, Podglądu zdarzeń, logi producenta i raporty testów.',`Szukaj korelacji między błędem a etapem opisanym w lekcji „${title}”.`,['Zapisz pełny kod i źródło komunikatu.','Porównaj czas zdarzeń z historią aktualizacji lub zmian.','Nie publikuj numerów seryjnych, kluczy BitLocker ani danych osobowych.']],
      ['O','Test izolacyjny i zawężanie obszaru','Zredukuj konfigurację do minimalnego, bezpiecznego zestawu. Odłączaj tylko peryferia, które można bezpiecznie odłączyć.',`Celem jest ustalenie, czy przyczyna należy do: ${p.label}, systemu, zasilania, przewodu czy akcesorium.`,['Testuj jeden element na raz.','Porównaj inne gniazdo, przewód, profil użytkownika lub sieć, gdy ma to zastosowanie.','Po każdym teście wróć do zapisanej konfiguracji.']],
      ['P','Porównanie z częścią lub konfiguracją sprawną','Porównanie ma sens tylko przy potwierdzonej zgodności generacji, modelu, firmware, parametrów elektrycznych i sposobu montażu.',`Nie zakładaj, że identyczny kształt złącza oznacza zgodność z „${title}”.`,['Użyj znanego sprawnego elementu o potwierdzonych parametrach.','Nie przekładaj części, jeśli może to naruszyć gwarancję lub bezpieczeństwo.','Po teście odtwórz konfigurację i udokumentuj wynik.']],
      ['Q','Zabezpieczenie danych i punkt kontrolny','Przed operacją zapisu, aktualizacją firmware, formatowaniem, naprawą systemu plików lub resetem ustal, czy dane są zabezpieczone.',`W tematach dotyczących ${p.label} dobierz kopię, obraz lub punkt przywracania do ryzyka. Przy podejrzeniu awarii nośnika najpierw zabezpiecz dane.`,['Potwierdź, które dane mają zostać zachowane.','Sprawdź, czy kopia jest czytelna i znajduje się na innym nośniku.','Przed operacjami BitLocker uzyskaj klucz od właściciela — nigdy nie żądaj wysłania go na czat.']],
      ['R','Właściwa procedura naprawcza','Wykonaj wyłącznie działanie wynikające z potwierdzonego testu. Używaj instrukcji producenta i właściwych części.',`Bezpieczny pierwszy krok dla tej lekcji: ${c.teaching.first}`,['Przygotuj odpowiednie narzędzia i część zgodną z modelem.','Dokumentuj demontaż, kolejność złącz i momenty dokręcania podane przez OEM.','Przerwij, jeśli odkryjesz uszkodzenie, którego nie obejmuje procedura.']],
      ['S','Weryfikacja specyfikacji i kompatybilności','Sprawdź generację, interfejs, napięcie, moc, pojemność, format, obsługiwane tryby i ograniczenia firmware.',`Dla „${title}” potwierdź zgodność części lub ustawienia z dokumentacją urządzenia.`,['Sprawdź numer katalogowy i rewizję.','Potwierdź obsługę przez płytę/BIOS i system.','Nie używaj przypadkowych adapterów ani plików firmware.']],
      ['T','Sterowniki, system i aktualizacje','Aktualizuj tylko wtedy, gdy objaw wskazuje na warstwę programową, a znana jest wersja systemu i sprzętu.',`W przypadku „${title}” pobieraj sterownik z OEM lub bezpośrednio od dostawcy układu.`,['Utwórz punkt przywracania lub kopię konfiguracji, gdy to właściwe.','Zapisz obecną wersję i datę sterownika.','Sprawdź znane problemy i wymagania wersji przed instalacją.']],
      ['U','UEFI, firmware i konfiguracja rozruchu','Zmiany firmware wykonuj tylko po identyfikacji modelu, rewizji, pliku i procedury. Zabezpiecz klucz odzyskiwania BitLocker.',`Etap firmware dla tej kategorii: ${p.id==='bios'?'sprawdzenie dokładnego BIOS/UEFI i instrukcji OEM':p.id==='storage'?'sprawdzenie firmware SSD/NVMe w narzędziu producenta':p.id==='network'?'sprawdzenie firmware routera i jego rewizji':'zmieniaj firmware tylko wtedy, gdy producent wskazuje je jako właściwe dla tego objawu'}.`,['Zweryfikuj sumę kontrolną i podpis, jeśli producent je udostępnia.','Zapewnij stabilne zasilanie i nie przerywaj aktualizacji.','Nie wykonuj downgrade bez potwierdzonej procedury.']],
      ['V','Weryfikacja pod obciążeniem i stabilność','Po naprawie powtórz test pierwotnego objawu, a następnie krótki test funkcji w kontrolowanych warunkach.',`Dla ${p.label} dobierz test: ${p.tests[0]||'test funkcji zgodny z dokumentacją'}.`,['Monitoruj temperaturę, błędy i stabilność.','Przerwij przy zapachu, dymie, przegrzewaniu, artefaktach lub resetach.','Nie rób długiego testu obciążeniowego, zanim potwierdzisz chłodzenie i zasilanie.']],
      ['W','Wynik, raport i dokumentacja serwisowa','Raport powinien pozwalać drugiemu technikowi odtworzyć diagnozę i sprawdzić rezultat.',`Do raportu wpisz: objaw „${title}”, hipotezę, test, wynik przed/po oraz użyte źródło.`,['Dodaj model i rewizję, ale nie ujawniaj danych poufnych.','Zapisz wersję sterownika/BIOS lub numer testu.','Dołącz wyłącznie zanonimizowane zdjęcia i raporty.']],
      ['X','Eskalacja i granice samodzielnej naprawy','Przerwij, jeśli wymagane są pomiary niebezpieczne, praca po stronie sieciowej, uszkodzona bateria, zalanie, uszkodzenie płyty lub brak dokumentacji.',`W tym temacie eskaluj do specjalisty, gdy wynik nie daje się jednoznacznie odtworzyć lub wykracza poza bezpieczne czynności.`,['Nie mostkuj bezpieczników ani zabezpieczeń.','Nie otwieraj zasilaczy sieciowych.','Nie wykonuj naprawy danych, jeśli nośnik mechanicznie uszkodzony wymaga laboratorium.']],
      ['Y','Wyjaśnienie wyniku właścicielowi sprzętu','Opisz ustaloną przyczynę, zakres prac, ryzyka, ograniczenia testu, użyte części i to, co nadal wymaga obserwacji.',`Wynik dotyczący „${title}” przedstaw jako: potwierdzone / prawdopodobne / nierozstrzygnięte — nie obiecuj 100% sprawności na podstawie krótkiego testu.`,['Uzgodnij utratę gwarancji lub ryzyko przed pracą.','Przekaż informację o kopii danych i sposobie użycia sprzętu.','Przekaż jasne zalecenia konserwacyjne i gwarancję usługi.']],
      ['Z','Zamknięcie naprawy i kontrola końcowa','Zamknij sprawę dopiero po sprawdzeniu wszystkich funkcji, powtórzeniu pierwotnego objawu i zapisaniu raportu.',`Ostateczny test dla „${title}”: ${p.tests.slice(0,2).join(' ')}`,['Usuń narzędzia diagnostyczne i przywróć uzgodnioną konfigurację.','Sprawdź porty, obudowę, przewody, datę/czas i aktualny stan urządzenia.','Oznacz wynik: naprawiono, częściowo naprawiono lub wymaga dalszej diagnostyki.']]
    ];
    return stages.map(([letter,head,lead,context,checks])=>({letter,head,lead,context,checks}));
  };
  const buildGuide = (item,tab) => {
    const c=createContext(item,tab), p=c.profile;
    const title=c.title;
    const baseSteps=c.originalSteps.length?c.originalSteps:p.steps;
    const desc=c.description;
    const sourcesHtml=c.sources.map(s=>`<a class="az-source" href="${esc(s.url)}" target="_self" rel="noopener"><span>${esc(s.kind)}</span><b>${esc(s.title)}</b><small>${esc(s.desc)}</small><em>${esc(s.updated)}</em></a>`).join('');
    const isEnglish=(()=>{try{return localStorage.getItem('academyLanguage')==='en'}catch{return false}})();
    const guidesHtml=(item.guides||[]).map((g,i)=>`<details class="az-original-guide"><summary>${esc((isEnglish&&g.titleEn)||g.title||`Procedura źródłowa ${i+1}`)}</summary><div>${esc((isEnglish&&g.bodyEn)||g.body||'')}</div></details>`).join('');
    const original = item.body && item.body!==desc ? `<details class="az-source-original"><summary>Pełna treść materiału źródłowego tej lekcji</summary><p>${esc(item.body)}</p></details>` : '';
    const sourceNotes = item.source ? `<p class="az-origin-note">Materiał bazowy: ${esc(item.source)}${item.sourcePage?` · strona/sekcja: ${esc(item.sourcePage)}`:''}. Treść źródłowa pozostaje dostępna w Bibliotece Akademii.</p>` : '';
    const defaultQuiz=[
      {q:`Jaki jest pierwszy bezpieczny krok w temacie „${title}”?`,a:c.teaching.first},
      {q:'Co musi poprzedzić wymianę części?',a:'Potwierdzenie przyczyny powtarzalnym testem, sprawdzenie zgodności części i zabezpieczenie danych.'},
      {q:'Czy jeden test bez błędów gwarantuje pełną sprawność?',a:'Nie. Zapisz warunki, zakres i ograniczenia testu; powtórz scenariusz pierwotnego objawu.'},
      {q:'Co zrobić, gdy brakuje dokumentacji dokładnego modelu?',a:'Nie zgaduj pinów, napięć ani firmware. Zdobądź dokumentację zgodną z modelem i rewizją albo przerwij ryzykowną czynność.'}
    ];
    const quiz=Array.isArray(item.quiz)&&item.quiz.length?item.quiz:defaultQuiz;
    const quizHtml=quiz.map((raw,i)=>{
      const q=Array.isArray(raw)?{q:raw[0],options:raw[1],correct:raw[2]}:raw||{};
      if(Array.isArray(q.options)&&q.options.length>=2&&Number.isInteger(Number(q.correct))){
        const options=q.options.map((option,j)=>`<button type="button" class="az-quiz-option" data-az-quiz-answer="${j}">${esc(option)}</button>`).join('');
        return `<div class="az-quiz-question" data-az-quiz-question data-correct="${Number(q.correct)}"><p class="az-quiz-prompt">${i+1}. ${esc(q.q||'Pytanie')}</p><div class="az-quiz-options">${options}</div><p class="az-quiz-feedback" data-az-quiz-feedback aria-live="polite"></p><span hidden data-az-quiz-explanation>${esc(q.explain||'')}</span></div>`;
      }
      return `<details><summary>${i+1}. ${esc(q.q||'Pytanie')}</summary><p>${esc(q.a||q.answer||q.explain||'')}</p></details>`;
    }).join('');
    const interactiveQuiz=quiz.length>0&&quiz.every(raw=>{const q=Array.isArray(raw)?{options:raw[1],correct:raw[2]}:raw||{};return Array.isArray(q.options)&&q.options.length>=2&&q.correct!==undefined&&Number.isInteger(Number(q.correct));});
    const quizBlock=interactiveQuiz?`<div class="az-quiz az-quiz-fix136" data-az-quiz-root><div class="az-quiz-status" data-az-quiz-status>Odpowiedz na pytania · 0 / ${quiz.length}</div>${quizHtml}<div class="az-quiz-result" data-az-quiz-result hidden></div></div>`:`<div class="az-quiz">${quizHtml}</div>`;
    const ex=item.exercise&&typeof item.exercise==='object'?item.exercise:null;
    const exerciseHtml=ex?`<section class="az-block az-wide" id="az-practice"><span class="az-letter">Ć</span><h3>Ćwiczenie warsztatowe</h3><div class="az-practice-fix136"><h4>SCENARIUSZ</h4><p>${esc(ex.scenario||'')}</p><h4>ZADANIE</h4><p>${esc(ex.task||'')}</p>${Array.isArray(ex.deliverable)?`<h4>CO MASZ PRZYGOTOWAĆ</h4><ul>${ex.deliverable.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<p class="az-practice-accept"><b>Kryterium zaliczenia:</b> ${esc(ex.acceptance||'')}</p></div></section>`:'';
    const guideKey=esc(c.key);
    const extraAlphabet = alphabetStages(c);
    const extraAlphabetHtml = extraAlphabet.map(st=>`<section class="az-block" id="az-${st.letter.toLowerCase()}"><span class="az-letter">${st.letter}</span><h3>${esc(st.head)}</h3><p>${esc(st.lead)}</p><div class="az-context-card"><b>W odniesieniu do tej lekcji</b><p>${esc(st.context)}</p></div><ul class="az-bullets">${st.checks.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>`).join('');
    const extraAlphabetLinks = extraAlphabet.map(st=>`<a href="#az-${st.letter.toLowerCase()}">${st.letter} · ${esc(st.head.split(' ').slice(0,2).join(' '))}</a>`).join('');
    const stepsHtml=baseSteps.map((x,i)=>`<label class="az-task"><input type="checkbox" data-guide-check="${guideKey}" data-guide-index="${i}"><span><b>Krok ${i+1}</b>${esc(x)}</span></label>`).join('');
    const profileNotes=item.diagnosis?`<div class="az-context-card"><b>Treść diagnozy w tym materiale</b><p>${esc(item.diagnosis)}</p></div>`:'';
    const repairNotes=item.repair?`<div class="az-context-card"><b>Rozwiązania wskazane w tym materiale</b><p>${esc(item.repair)}</p></div>`:'';
    const symptomNotes=item.symptoms?`<div class="az-context-card"><b>Objawy do rozpoznania</b><p>${esc(item.symptoms)}</p></div>`:'';
    const safetyNote=item.warning||p.safety;
    const lessonTools=Array.isArray(item.tools)&&item.tools.length?item.tools:p.tools;
    const todoKey=encodeURIComponent(c.key);
    return `<div class="az-course"><div class="az-course-banner"><span class="eyebrow">KURS KOMPLETNY / ŚCIEŻKA A–Z</span><h2>${esc(title)}</h2><p>${esc(desc)}</p><div class="az-meta"><span>${esc(item.level||item.category||p.label)}</span><span>Poziom: ${esc(item.level||'podstawowy → praktyka')}</span><span>Indywidualna ścieżka i czat</span></div></div>${renderFlowChart(c)}<div class="az-outline"><a href="#az-a">A · Cel</a><a href="#az-b">B · Pojęcia</a><a href="#az-c">C · Narzędzia</a><a href="#az-d">D · Bezpieczeństwo</a><a href="#az-e">E · Diagnoza</a><a href="#az-practice">Ć · Praktyka</a><a href="#az-f">F · Rozwiązania</a><a href="#az-g">G · Test</a><a href="#az-h">H · Błędy</a><a href="#az-i">I · Quiz</a>${extraAlphabetLinks}<a href="#az-sources">Ź · Źródła</a></div><div class="az-grid"><section class="az-block" id="az-a"><span class="az-letter">A</span><h3>Cel nauki i rezultat</h3><p>Po tej lekcji powinieneś umieć rozpoznać temat <b>${esc(title)}</b>, opisać objawy, dobrać bezpieczny test i rozróżnić hipotezę od potwierdzonej przyczyny.</p><p>${esc(desc)}</p>${symptomNotes}</section><section class="az-block" id="az-b"><span class="az-letter">B</span><h3>Pojęcia i jak to działa</h3><p><b>${esc(p.label)}.</b> ${esc(c.teaching.explain)}</p><div class="az-context-card"><b>Najbezpieczniejszy pierwszy krok</b><p>${esc(c.teaching.first)}</p></div><p>Najważniejsza zasada: jeden test powinien sprawdzać jedną hipotezę, a wynik zapisuj wraz z warunkami i dokładnym modelem sprzętu.</p>${original}</section><section class="az-block" id="az-c"><span class="az-letter">C</span><h3>Co przygotować</h3>${bullets(lessonTools)}<h4>Przygotowanie stanowiska</h4>${list(p.prep)}</section><section class="az-block az-warning-block" id="az-d"><span class="az-letter">D</span><h3>Bezpieczeństwo</h3><p>${esc(safetyNote)}</p><p>Nie zakładaj, że polecenie, napięcie, pinout lub plik firmware są uniwersalne. Weryfikuj je dla konkretnego modelu i rewizji.</p></section><section class="az-block az-wide" id="az-e"><span class="az-letter">E</span><h3>Diagnostyka krok po kroku</h3><p>Wykonaj kolejne kroki po kolei. Zaznacz etap po zakończeniu — postęp zapisuje się w tej przeglądarce.</p><div class="az-task-list">${stepsHtml}</div>${profileNotes}${guidesHtml}</section>${exerciseHtml}<section class="az-block" id="az-f"><span class="az-letter">F</span><h3>Możliwe rozwiązania i interpretacja</h3>${bullets(p.solutions)}${repairNotes}<p class="az-small-note">Nie wymieniaj części na podstawie samego objawu. Naprawa ma wynikać z powtarzalnego testu i dokumentacji.</p></section><section class="az-block" id="az-g"><span class="az-letter">G</span><h3>Test po naprawie i potwierdzenie wyniku</h3>${list(p.tests)}<p>Powtórz dokładnie ten scenariusz, od którego rozpoczęto diagnozę. Zapisz konfigurację, temperatury/kody/wersje i wynik końcowy.</p></section><section class="az-block" id="az-h"><span class="az-letter">H</span><h3>Najczęstsze błędy początkujących</h3>${bullets(p.mistakes)}</section><section class="az-block az-wide" id="az-i"><span class="az-letter">I</span><h3>Sprawdź, czy rozumiesz temat</h3>${quizBlock}<p class="az-origin-note">Ćwiczenie: opisz objaw, hipotezę, test, wynik i decyzję naprawczą tak, aby drugi technik mógł odtworzyć Twoje rozumowanie.</p></section>${extraAlphabetHtml}<section class="az-block az-wide" id="az-sources"><span class="az-letter">Ź</span><h3>Oficjalne źródła online i narzędzia</h3><p>Odnośniki prowadzą bezpośrednio do producentów i dokumentacji. Przed pobraniem sprawdź dokładny model, wersję systemu, sumy kontrolne i warunki licencji.</p><div class="az-sources-grid">${sourcesHtml||'<p>Otwórz dział Źródła online w Akademii.</p>'}</div>${sourceNotes}</section></div>${chatHtml(c)}</div>`;
  };
  const response = question => {
    if(!ctx)return 'Najpierw otwórz konkretną lekcję.';
    const q=String(question||'').toLowerCase(), p=ctx.profile, i=ctx.item;
    const sourceHtml=ctx.sources.slice(0,5).map(s=>`<p><a href="${esc(s.url)}" target="_self" rel="noopener"><b>${esc(s.title)}</b></a> — ${esc(s.desc)} <small>(${esc(s.updated)})</small></p>`).join('');
    let title='',body='';
    if(/najnowsz|aktualn|pobierz|źródł|link|oficjaln|wersj[ae]/i.test(q)) { title='Aktualne źródła dla tego tematu'; body=`<p>Najpierw korzystaj z dokumentacji producenta urządzenia lub systemu. Poniżej są źródła przypisane do kategorii <b>${esc(p.label)}</b>:</p>${sourceHtml||'<p>Brak bezpośredniego źródła w tej kategorii. Otwórz zakładkę „Źródła online” w Akademii.</p>'}<p>Przed instalacją sprawdź model, rewizję, system, wersję pliku i podpis cyfrowy. Nie pobieraj sterowników ani firmware z nieoficjalnych agregatorów.</p>`; }
    else if(/narzędz|sprzęt|przygot|czym|czego użyć/i.test(q)) {title='Narzędzia i przygotowanie';body=`<p>Do tematu <b>${esc(ctx.title)}</b> przygotuj:</p>${bullets(p.tools)}<p>Przed pracą:</p>${list(p.prep)}`;}
    else if(/bezpie|ryzyk|prąd|bater|spuch|dym|zwar/i.test(q)) {title='Zasady bezpieczeństwa';body=`<p>${esc(i.warning||p.safety)}</p><p>${esc(p.safety)}</p><p>Jeśli nie masz instrukcji dokładnego modelu, odpowiednich narzędzi lub kwalifikacji do pomiaru, zatrzymaj się i zleć czynność technikowi.</p>`;}
    else if(/test|sprawdź|sprawdzi|wynik|po napraw/i.test(q)) {title='Jak sprawdzić wynik';body=`${list(p.tests)}<p>Powtórz objaw w tych samych warunkach, porównaj zapis przed/po i upewnij się, że nie pojawiły się nowe błędy.</p>`;}
    else if(/napraw|rozwią|wymieni|fix|usterk/i.test(q)) {title='Droga od przyczyny do rozwiązania';body=`${bullets(p.solutions)}${ctx.repairs?`<div class="az-context-card"><b>Rozwiązanie zapisane w materiale</b><p>${esc(ctx.repairs)}</p></div>`:''}<p>Najpierw potwierdź przyczynę niezależnym testem. Dobierz część tylko po numerze/modelu i specyfikacji, a potem wykonaj test końcowy.</p>`;}
    else if(/błąd|nie dział|nadal|problem|diagnoz|krok|zaczą|od czego|sprawdza/i.test(q)) {title='Kolejność diagnostyki';body=`<p>Nie zaczynaj od wymiany części. Dla tej lekcji wykonaj:</p>${list(p.steps)}${ctx.diagnosis?`<div class="az-context-card"><b>Objawy/diagnoza z materiału</b><p>${esc(ctx.diagnosis)}</p></div>`:''}<p>Zapisz dokładny wynik każdego kroku. Zmieniaj tylko jeden czynnik naraz.</p>`;}
    else if(/przyczyn|dlaczego|objaw|skąd|powod|powód/i.test(q)) {title='Jak zawęzić przyczynę w tej lekcji';body=`<p><b>Temat:</b> ${esc(ctx.title)}.</p>${ctx.diagnosis?`<div class="az-context-card"><b>Objawy i diagnoza w materiale</b><p>${esc(ctx.diagnosis)}</p></div>`:''}${i.symptoms?`<div class="az-context-card"><b>Objawy do porównania</b><p>${esc(i.symptoms)}</p></div>`:''}${bullets(p.solutions)}<p>Każda możliwa przyczyna musi mieć osobny test. Nie uznawaj korelacji za potwierdzenie uszkodzenia części.</p>`;}
    else if(/pierwsz|zaczn|co zrobić|co robic|od czego|krok/i.test(q)) {title='Co zrobić najpierw';body=`<p>${esc(ctx.teaching.first)}</p>${list(p.prep)}<p>Następnie wykonaj tylko te kroki, które pasują do modelu i nie naruszają warunków bezpieczeństwa:</p>${list(p.steps)}`;}
    else {title='Wyjaśnienie tematu od podstaw';body=`<p><b>${esc(ctx.title)}</b> należy do obszaru: ${esc(p.label)}.</p><p>${esc(ctx.description)}</p><p>${esc(ctx.teaching.explain)}</p><div class="az-context-card"><b>Najbezpieczniejszy pierwszy krok</b><p>${esc(ctx.teaching.first)}</p></div><p>Jeśli opiszesz dokładny objaw, model urządzenia i etap, na którym zatrzymuje się praca, dopasuję odpowiedź do materiału tej lekcji. Nie podawaj haseł, kluczy BitLocker ani danych osobowych.</p>`;}
    return `<div><b>${esc(title)}</b>${body}</div>`;
  };
  const renderOnline = () => {
    const root=document.getElementById('onlineSourcesGrid'); if(!root)return;
    const q=(document.getElementById('onlineSourceSearch')?.value||'').toLowerCase();
    const cat=document.getElementById('onlineSourceCategory')?.value||'all';
    const matches=sources.filter(s=>(cat==='all'||s.category===cat)&&[s.title,s.category,s.desc,s.tags.join(' ')].join(' ').toLowerCase().includes(q));
    root.innerHTML=matches.map(s=>`<article class="online-source-card"><div class="online-source-type">${esc(s.kind)}</div><h3>${esc(s.title)}</h3><span class="online-source-cat">${esc(s.category)}</span><p>${esc(s.desc)}</p><small>${esc(s.updated)}</small><a href="${esc(s.url)}" target="_self" rel="noopener">Otwórz oficjalne źródło →</a></article>`).join('');
    const count=document.getElementById('onlineSourceCount'); if(count)count.textContent=`${matches.length} / ${sources.length} źródeł`;
  };
  // FIX136: delegated quiz grading works for dynamically inserted lesson modals.
  if (!window.__ACADEMY_FIX136_QUIZ_BOUND) {
    window.__ACADEMY_FIX136_QUIZ_BOUND = true;
    document.addEventListener('click', event => {
      const button = event.target?.closest?.('[data-az-quiz-answer]');
      if (!button) return;
      const question = button.closest('[data-az-quiz-question]');
      const root = button.closest('[data-az-quiz-root]');
      if (!question || !root || question.dataset.answered === 'true') return;
      const chosen = Number(button.dataset.azQuizAnswer);
      const correct = Number(question.dataset.correct);
      const good = chosen === correct;
      question.dataset.answered = 'true';
      question.dataset.wasCorrect = String(good);
      question.querySelectorAll('[data-az-quiz-answer]').forEach(option => {
        option.disabled = true;
        if (Number(option.dataset.azQuizAnswer) === correct) option.classList.add('is-correct');
        else if (option === button && !good) option.classList.add('is-wrong');
      });
      const explanation = question.querySelector('[data-az-quiz-explanation]')?.textContent || '';
      const feedback = question.querySelector('[data-az-quiz-feedback]');
      if (feedback) feedback.textContent = `${good ? 'Poprawna odpowiedź.' : 'To nie jest poprawna odpowiedź.'} ${explanation}`.trim();
      const questions = [...root.querySelectorAll('[data-az-quiz-question]')];
      const answered = questions.filter(item => item.dataset.answered === 'true');
      const score = questions.filter(item => item.dataset.answered === 'true' && item.dataset.wasCorrect === 'true').length;
      const status = root.querySelector('[data-az-quiz-status]');
      if (status) status.textContent = `Odpowiedzi: ${answered.length} / ${questions.length} · poprawne: ${score}`;
      if (answered.length === questions.length) {
        const result = root.querySelector('[data-az-quiz-result]');
        if (result) {
          result.hidden = false;
          result.textContent = `Wynik końcowy: ${score} / ${questions.length}. ${score === questions.length ? 'Bardzo dobrze — wszystkie odpowiedzi poprawne.' : score >= Math.ceil(questions.length * 0.67) ? 'Dobry wynik. Wróć do pytań, które sprawiły trudność.' : 'Powtórz materiał i wykonaj quiz ponownie po przejrzeniu procedury.'}`;
        }
      }
    });
  }
  window.ACADEMY_LEARNING_ENGINE={buildGuide,response,renderOnline,getContext:()=>ctx,clear:()=>{ctx=null;},sources};
})();
